B.hR=new A.oV(2,"timer")
B.EE=new A.eG("meditate","\uba85\uc0c1","Meditate","\ud3b8\ud558\uac8c \uc549\uc544 \uc18c\ub9ac\ub97c \ud2c0\uace0 \ud638\ud761\uc5d0 \uc9d1\uc911\ud558\uc138\uc694. {m}\ubd84\uc774 \uc9c0\ub098\uba74 \uc644\ub8cc\ud560 \uc218 \uc788\uc5b4\uc694.","Sit comfortably, play a sound and focus on your breath. You can check it off after {m} minutes.",10,B.hR,B.dP)
